  if (id!==1) { await tools.back_to_search(); await tools.open_product({id}); }
  out.push(await tools.get_product());
  out.push(await tools.add_to_cart({quantity:1}));
}
await tools.back_to_search();
out.push(await tools.cart_size());
return out;

