declare const tools: {
  /**
   * Search the catalog by keyword and optional category. Returns matching products with id, name and price.
   * (read-only)
   */
  search_products(args: {
    /** Keyword, matched against product names */
    query: string;
    category?: "kitchen" | "office";
  }): Promise<unknown>;
  /** Open the product page for a product id. The product page has tools to read details and add to cart. */
  open_product(args: {
    id: number;
  }): Promise<unknown>;
  /** Open the cart page. */
  go_to_cart(args?: {}): Promise<unknown>;
  /** Always throws, for tests. */
  fail(args?: {}): Promise<unknown>;
  /**
   * The customer's past orders, oldest first: id, date (YYYY-MM-DD), status (delivered, returned or canceled), shipping, items (productId, name, category, quantity, unitPrice) and total.
